def compute(vars):
    chemical_freight_revenue = vars["v1"]
    total_operating_revenues = vars["v2"]

    if total_operating_revenues == 0:
        return None

    percentage = (chemical_freight_revenue / total_operating_revenues) * 100

    return {
        "value": round(percentage, 3),
        "trace": {
            "chemical_freight_revenue": chemical_freight_revenue,
            "total_operating_revenues": total_operating_revenues,
            "ratio": chemical_freight_revenue / total_operating_revenues,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
